import java.util.*;
public class FinalHarness{static int p=0;static List<String> f=new ArrayList<>();static Map<String,String> extract(String s){Map<String,String> m=new HashMap<>();if(s.matches(".*\\d+.*"))m.put("amount",s.replaceAll(".*?(\\d+).*","$1"));if(s.toLowerCase().contains("swiggy"))m.put("merchant","Swiggy");return m;}static String cat(String s){s=s.toLowerCase();return s.contains("food")||s.contains("swiggy")?"Food":"Other";}static boolean release(boolean signed,boolean privacy,boolean noDebug){return signed&&privacy&&noDebug;}static int contrast(int a,int b){return Math.abs(a-b);}static void eq(String n,Object e,Object a){if(Objects.equals(e,a))p++;else f.add(n+" expected "+e+" got "+a);}public static void main(String[]a){eq("extract amount","250",extract("spent 250 at swiggy").get("amount"));eq("extract merchant","Swiggy",extract("spent 250 at swiggy").get("merchant"));eq("categorize","Food",cat("swiggy dinner"));eq("fallback category","Other",cat("misc"));eq("release gate",true,release(true,true,true));eq("release fail",false,release(true,false,true));eq("contrast",200,contrast(250,50));System.out.println("PASSED: "+p+" assertions");if(!f.isEmpty()){f.forEach(System.out::println);System.exit(1);}System.out.println("ALL FINAL PHASE CHECKS PASSED");}}
